CREATE DATABASE IF NOT EXISTS time_to_trip CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE time_to_trip;
CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trips(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,host_id INT UNSIGNED NOT NULL,title VARCHAR(150) NOT NULL,from_city VARCHAR(100) NOT NULL,to_place VARCHAR(120) NOT NULL,travel_date DATE NOT NULL,seats_total TINYINT UNSIGNED NOT NULL DEFAULT 2,seats_available TINYINT UNSIGNED NOT NULL DEFAULT 2,estimated_cost DECIMAL(10,2) NOT NULL DEFAULT 0,duration_days TINYINT UNSIGNED NOT NULL DEFAULT 1,travel_style ENUM('beach','nature','culture','city','other') NOT NULL DEFAULT 'other',trip_type ENUM('group','carpool') NOT NULL DEFAULT 'group',description TEXT NULL,vehicle VARCHAR(120) NULL,luggage_notes VARCHAR(255) NULL,status ENUM('open','closed','cancelled') NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_trips_host FOREIGN KEY(host_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_trip_search(trip_type,travel_date,from_city,to_place,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trip_requests(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,trip_id INT UNSIGNED NOT NULL,requester_id INT UNSIGNED NOT NULL,seats_requested TINYINT UNSIGNED NOT NULL DEFAULT 1,message VARCHAR(500) NULL,status ENUM('pending','accepted','declined','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_trip_request(trip_id,requester_id),CONSTRAINT fk_request_trip FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE CASCADE,CONSTRAINT fk_request_user FOREIGN KEY(requester_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
